		rcvrOrClosure = longAt(theFP + ((FoxCallerSavedIP + BytesPerWord) + ((((usqInt)((/* frameNumArgs: */
	((((usqInt)(longAt(theFP + FoxMethod)))) < (startOfMemory())
		? ((mframeCogMethod(theFP))->cmNumArgs)
		: byteAt((theFP + FoxIFrameFlags) + 1)))) << (shiftForWord()))))));
