	kernDelta = (kernDelta >> 1);
	scanRightX = (scanRightX >> 1);
	scanStopIndex = (scanStopIndex >> 1);
	scanStartIndex = (scanStartIndex >> 1);

	/* check argument type and range and rcvr */
	if (!((/* isArray: */
			((stops & 1) == 0)
		 && (((((usqInt)((longAt((void *)(stops))))) >> (instFormatFieldLSB())) & 15) == 2))
		 && (((slotSizeOf(stops)) >= 258)
		 && ((/* isBytes: */
			((sourceString & 1) == 0)
		 && (((((usqInt)((longAt((void *)(sourceString))))) >> (instFormatFieldLSB())) & 15) >= (firstByteFormat())))
		 && ((scanStartIndex > 0)
		 && ((scanStopIndex > 0)
		 && (scanStopIndex <= (byteSizeOf(sourceString))))))))) {
		/* primitiveFailFor: */
		GIV(primFailCode) = PrimErrBadArgument;
		return;
	}
