	storeIntegerofObjectwithValue(0, rcvr, scanDestX);
	storeIntegerofObjectwithValue(1, rcvr, scanStopIndex);

	/* begin methodReturnValue: */
	assert(!((failed())));
	longAtput((GIV(stackPointer) += ((GIV(argumentCount) + 1) - 1) * BytesPerWord),longAt((void *)((stops + BaseHeaderSize) + ((((usqInt)((EndOfRun - 1)) << (shiftForWord())))))));
