/*	For the purposes of become: send selector to the cogit with obj1, obj2 and
	aBool, and
	answer the result. Undo forwarding for the selector, but redo forwarding
	after since
	become:'s restoreHeadersAfter*Become* methods expect to be able to
	restore. 
 */

	/* NewCoObjectMemory>>#withoutForwardingOn:and:with:sendToCogit: */
sqInt
withoutForwardingOnandwithsendToCogit(sqInt obj1, sqInt obj2, sqInt aBool, sqInt (*selector)(sqInt,sqInt,sqInt))
{
    sqInt aWord;
    usqInt fwdBlock;
    sqInt header;
    sqInt result;
    sqInt savedHeaderA;
    sqInt savedHeaderB;

	savedHeaderA = longAt((void *)(obj1));

	/* begin headerWhileForwardingOf: */
	header = longAt((void *)(obj1));
	if (header & MarkBit) {
		/* oop is forwarded; get its real header from its forwarding table entry */
		fwdBlock = ((header & AllButMarkBitAndTypeMask) << 1);
		assert(fwdBlockValid(fwdBlock));
		header = longAt((void *)(fwdBlock + BytesPerWord));
	}
	aWord = header;

	/* begin baseHeader:put: */
	longAtput((void *)(obj1),aWord);
	savedHeaderB = longAt((void *)(obj2));

	/* begin headerWhileForwardingOf: */
	header = longAt((void *)(obj2));
	if (header & MarkBit) {
		/* oop is forwarded; get its real header from its forwarding table entry */
		fwdBlock = ((header & AllButMarkBitAndTypeMask) << 1);
		assert(fwdBlockValid(fwdBlock));
		header = longAt((void *)(fwdBlock + BytesPerWord));
	}
	aWord = header;

	/* begin baseHeader:put: */
	longAtput((void *)(obj2),aWord);
	result = selector(obj1, obj2, aBool);

	/* baseHeader:put: */
	longAtput((void *)(obj1),savedHeaderA);

	/* baseHeader:put: */
	longAtput((void *)(obj2),savedHeaderB);
	return result;
}

	/* NewCoObjectMemory>>#youngStartAddress */
