	if (hdr & TypeMask) {
		sz = hdr & SizeMask;
	}
	else {
		sz = (longAt((void *)(obj - (BytesPerWord * 2)))) & LongSizeMask;
	}
	sz -= 0;
	if (fmt <= 4 /* lastPointerFormat */) {
		totalLength = ((usqInt)((sz - BaseHeaderSize))) >> (shiftForWord());
		goto l1;
	}
	totalLength = (fmt < (firstByteFormat())
				? ((usqInt)((sz - BaseHeaderSize))) >> 2
				: (sz - BaseHeaderSize) - (fmt & 3));
	/* end lengthOf:baseHeader:format: */
l1:

	/* begin fixedFieldsOf:format:length: */
	if ((fmt > 4 /* lastPointerFormat */)
	 || (fmt == (arrayFormat()))) {
		fixedFields = 0;
		goto l2;
	}
	if (fmt < 2) {
		fixedFields = totalLength;
		goto l2;
	}
	class = /* fetchClassOfNonImm: */
			((ccIndex = (((usqInt)((longAt((void *)(obj))))) >> (compactClassFieldLSB())) & 0x1F)
				? longAt((void *)(((longAt((void *)((GIV(specialObjectsOop) + BaseHeaderSize) + ((((usqInt)(CompactClasses) << (shiftForWord()))))))) + BaseHeaderSize) + ((((usqInt)((ccIndex - 1)) << (shiftForWord()))))))
				: ((sqInt)((longAt((void *)(obj - BaseHeaderSize))) & AllButTypeMask)));
	classFormat = (longAt((void *)((class + BaseHeaderSize) + ((((usqInt)(InstanceSpecificationIndex) << (shiftForWord()))))))) - 1;
	fixedFields = (((((usqInt)(classFormat)) >> 11) & 192) + ((((usqInt)(classFormat)) >> 2) & 0x3F)) - 1;
	/* end fixedFieldsOf:format:length: */
