	longAtput((void *)(arrayOfRoots),(longAt((void *)(arrayOfRoots))) | MarkBit);
	lastPtr = arrayOfRoots + (lastPointerOf(arrayOfRoots));
	fieldPtr = arrayOfRoots + BaseHeaderSize;
