	minFree = ((((((GIV(lowSpaceThreshold) + bytes) + BaseHeaderSize) + BytesPerWord) - 1) | (BytesPerWord - 1)) - (BytesPerWord - 1));

	/* check for low-space */
	if (oopisLessThanOrEqualTo(GIV(freeStart) + minFree, GIV(reserveStart))) {
		return 1;
	}
	return sufficientSpaceAfterGC(minFree);
