	sz -= 0;
	if (fmt <= 4 /* lastPointerFormat */) {
		return ((usqInt)((sz - BaseHeaderSize))) >> (shiftForWord());
	}
	return (fmt < (firstByteFormat())
			? ((usqInt)((sz - BaseHeaderSize))) >> 2
			: (sz - BaseHeaderSize) - (fmt & 3));
