		header = ((header & 1)
					? header
					: (assert((((usqInt)header)) < (heapBase)),
					assert((((((CogMethod *) header))->objectHeader)) == (nullHeaderForMachineCodeMethod())),
					((((CogMethod *) header))->methodHeader)));

