		fprintf(GIV(transcript), " HeaderTypeShort (4 bytes)");
		break;
	case HeaderTypeClass:
		fprintf(GIV(transcript), " HeaderTypeClass (8 bytes)");
		break;
	case HeaderTypeSizeAndClass:
		fprintf(GIV(transcript), " HeaderTypeSizeAndClass (12 bytes)");
		break;
