		print("sender   ");
		printNum(sender);
		print(" (");
		printHexPtrnp(
			(/* begin withoutSmallIntegerTags: */
				assert((sender & 1)),
			((char *)(sender - 1 /* smallIntegerTag */))));
		printChar(')');
		cr();
